mapper.sql:
FROM audit_event a


        LEFT JOIN identity p ON p.id = a.actor_id AND NOT p.deleted
        WHERE a.realm = 'tenant' AND a.tenant_id = #{tenantId}


        LEFT JOIN operator p ON p.id = a.actor_id AND NOT p.deleted
        WHERE a.realm = 'platform'


AND a.occurred_at >= #{query.from}
AND a.occurred_at < #{query.to}
AND a.action = #{query.action}
AND a.resource_type = #{query.resourceType}
AND a.resource_id = #{query.resourceId}

    AND (strpos(lower(coalesce(p.account, '')), lower(#{query.actor})) > 0
        OR strpos(lower(coalesce(p.display_name, '')), lower(#{query.actor})) > 0)
